// Generated by Claude - Opus 5.5
import type { EngineInterface, Register, ThemeSetArgs } from 'claude-code'

import { visitPhase, VISITORS, type VisitorKind } from './layout'
import { makeColors } from './make-colors.js'
import { pond, type View } from './pond'

// --- 1. App colors from Molina and her pond, for light and dark mode.
const { theme, problems } = makeColors({
  label: "Molina's pond",
  roles: {
    accent: '#D97757', // Molina's coral gills: buttons, links, code keywords
    pro: '#E59AA0', // her pink body
    success: '#4E9F86', // kelp green
    danger: '#C4554D',
    warning: '#C99A3E',
  },
  light: {
    gray: {
      anchors: {
        'surface-0': '#E3F1EE', // pale pond water
        'surface-1': '#EAF5F2',
        'surface-2': '#F3FAF8',
        'surface-3': '#F3FAF8', // light mode: must match surface-2
        'text-primary': '#14232A',
        'text-secondary': '#3A4E55',
        'text-muted': '#56696F',
      },
    },
  },
  dark: {
    gray: {
      anchors: {
        'surface-0': '#0B1B22', // deep water at night
        'surface-1': '#10232B',
        'surface-2': '#152A33',
        'surface-3': '#1A303A',
        'text-primary': '#EAF2EF',
        'text-secondary': '#C2D1CF',
        'text-muted': '#93A6A6',
      },
    },
  },
})


// --- 2. Theme sound, tuned to A = 432 Hz (a tuning many people find calming).
// Notes are in hertz. The speaker button in the title bar turns it on.
const D = 288, E = 324, FS = 363.6, A = 432, B = 484.9 // D-E-F#-A-B: a pentatonic scale, no clashing notes

export const SOUND: ThemeSetArgs['sound'] = {
  ambience: {
    reverb: 0.4,
    layers: [
      // The melody (the first one, which you heard): three music-box phrases at
      // 60 BPM, half a beat a step, 0 a rest. The app starts one at random every
      // few seconds, so the tune drifts like a music box.
      ...[
        [A, 0, B, D * 2, 0, E * 2, D * 2], // rising
        [FS * 2, E * 2, D * 2, 0, B, A], // answer, falling
        [D, FS, A, 0, FS, E, D], // low lullaby
      ].map(notes => ({ wave: 'bell', notes, step: 0.5, scatter: 0.07, gain: 1, attack: 0.01, release: 0.8 }) as const),
      // Gently moving water.
      { wave: 'pink', drone: true, gain: 0.12, filter: { type: 'lowpass', hz: 900, to: 1300 }, tremolo: { hz: 0.07, depth: 0.5 } },
      // Bubbles, a fish "blub" now and then, and the jellyfish's airy shimmer.
      { wave: 'sine', notes: [A * 2, B * 2, FS * 2], scatter: 0.25, glide: 7, gain: 0.15, release: 0.1 },
      { wave: 'sine', notes: [E, FS], scatter: 0.06, glide: -5, gain: 0.18, attack: 0.01, release: 0.15 },
      { wave: 'sine', notes: [A * 3, B * 3], scatter: 0.04, glide: 12, gain: 0.1, attack: 0.6, release: 1.5, filter: { type: 'lowpass', hz: 2500 } },
    ],
  },
  // Molina's chimes (same steps as her desktop pet), in 432 tuning, full volume.
  cues: {
    send: { layers: [{ wave: 'sine', notes: [A * 2], glide: 12, gain: 1, release: 0.15 }] },
    tool: { layers: [{ wave: 'sine', notes: [E * 4], glide: 5, gain: 0.5, release: 0.06 }] },
    compact: { layers: [{ wave: 'sine', notes: [E * 2, A * 2, D * 4], step: 0.07, glide: 5, gain: 1, release: 0.2 }] },
    done: { reverb: 0.3, layers: [{ wave: 'bell', notes: [E * 2, A, D], step: 0.14, gain: 1, release: 1.2 }] },
    ask: { reverb: 0.3, layers: [{ wave: 'bell', notes: [D, A, E * 2], step: 0.14, gain: 1, release: 1.2 }] },
    error: { layers: [{ wave: 'bell', notes: [A / 2], gain: 1, release: 1.2 }] },
    click: { layers: [{ wave: 'bell', notes: [D * 2, E * 2, FS * 2, A * 2, B * 2], gain: 1, release: 1 }] },
  },
}

const LOOK: ThemeSetArgs = { colors: theme, backdrop: { scene: 'molina-pond' } } // no overrideColorScheme: follows your light/dark setting

// --- 3. What the pond shows. Module variables: they last for the session.
// Every redraw makes the app reload the picture (a brief flicker), so the pond
// redraws only when the badge moves a 5% step. Visitors run inside the
// drawing on a timetable.
type Engine = EngineInterface // the `$` every hook gets
let percent = 0 // context window, 0 to 100, in steps of 5
const stage = () => Math.min(3, Math.floor(percent / 25)) // 0 awake, 1 calm, 2 sleepy, 3 asleep
let settings = { sounds: true } // saved across sessions with /pond

const redraw = ($: Engine) => $.ui.invalidate('ui.render') // ask the app to draw the pond again

// --- 4. The animals' voices: short WAV files in sounds/, made by tools/make-sounds.mjs.
const play = ($: Engine, name: string) => {
  if (settings.sounds) $.audio.play({ asset: `sounds/${name}.wav` }, { gain: 1.4 }).catch(() => {})
}

// Visitors follow a fixed timetable from the clock (see layout.ts), which the
// drawing follows too, so each one calls out when it is actually on screen.
const callAhead = async ($: Engine, kind: VisitorKind) => {
  const v = VISITORS[kind]
  const phase = visitPhase(kind, await $.clock.now()) // seconds into its cycle
  const next = Math.min(...v.calls.map(c => (c > phase ? c : c + v.every)))
  $.clock.after((next - phase) * 1000, () => { play($, kind); void callAhead($, kind) })
}

const HELP = [
  "Molina's pond:",
  "  /pond sounds on|off     the visitors' calls",
  'Visitors (orca, sea turtle, manta ray, seahorse) drop by every few minutes.',
].join('\n')

export const register: Register = on => {
  // Session starts: apply the look and start the visitors' calls.
  on('session.start', async ($, e, next) => {
    const unpainted = problems.find(line => line.startsWith("Desktop won't paint"))
    if (unpainted !== undefined) $.ui.toast(unpainted)

    try {
      await $.theme.set({ ...LOOK, sound: SOUND })
    } catch (error) {
      $.ui.log(String(error)) // older app without sound: set the look alone
      $.ui.toast(`Molina's pond: sound was turned down (${String(error)}), so it plays silently`)
      await $.theme.set(LOOK)
    }
    settings = { ...settings, ...((await $.store.get('settings')) as Partial<typeof settings> | undefined) }
    await $.command.register({ name: 'pond', description: "Molina's pond: animal sounds on or off" })
    percent = Math.round(((await $.session.usage()).context.percent ?? 0) / 5) * 5
    for (const kind of Object.keys(VISITORS) as VisitorKind[]) if (VISITORS[kind].calls.length > 0) void callAhead($, kind) // the silent events have no calls
    return next(e)
  })

  // New usage figures arrive after each response: redraw only on a 5% step.
  on('session.measure', ($, e, next) => {
    const now = Math.round((e.context.percent ?? 0) / 5) * 5
    if (now !== percent) { percent = now; redraw($) }
    return next(e)
  })

  // /pond ...
  on('command.run', { command: 'pond' }, async ($, e) => {
    const [what = '', value = ''] = e.args.trim().toLowerCase().split(/\s+/)
    if (what === 'sounds' && (value === 'on' || value === 'off')) {
      settings = { ...settings, sounds: value === 'on' }
      await $.store.set('settings', settings)
      return { text: `Animal sounds ${value}.` }
    }
    return { text: HELP }
  })

  // Draw the pond in the desktop and mobile apps; leave other mods' scenes alone.
  on('ui.render', { component: 'Backdrop' }, async ($, e, next) => {
    if (e.surface !== 'desktop' && e.surface !== 'mobile') return next(e)
    if (e.props.scene !== 'molina-pond') return next(e)
    const { Svg } = $.ui.resolve(e)
    const view: View = { stage: stage(), percent, now: await $.clock.now() }
    return <Svg source={pond(view)} alt="Molina the pink axolotl on a rock in a pond full of sea life" />
  })
}
